-- PC-001C.1: provider-neutral Commerce catalog and append-only commercial history.
create table public.commerce_categories (id text primary key, slug text unique not null, name text not null, description text, active boolean not null default true, created_at timestamptz not null default now());
create table public.commerce_eligibility_policies (id text primary key, audience text not null check (audience in ('public','authenticated','workspace','owner','admin','invite-only','property-required','opportunity-required')), active boolean not null default true, configuration jsonb not null default '{}'::jsonb);
create table public.commerce_entitlement_templates (id text primary key, entitlement_key text unique not null, name text not null, description text not null, grant_quantity integer, metadata jsonb not null default '{}'::jsonb);
create table public.commerce_fulfillment_templates (id text primary key, fulfillment_type text not null, name text not null, handler_key text not null, configuration jsonb not null default '{}'::jsonb);
create table public.commerce_products (id text primary key, slug text unique not null, name text not null, short_description text not null, long_description text not null, category_id text not null references public.commerce_categories(id), product_type text not null, fulfillment_type text not null, status text not null check(status in ('draft','active','inactive','archived')), eligibility_policy_id text references public.commerce_eligibility_policies(id), entitlement_template_ids text[] not null default '{}', fulfillment_template_id text references public.commerce_fulfillment_templates(id), stripe_product_id text unique, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null, updated_at timestamptz not null);
create table public.commerce_prices (id text primary key, product_id text not null references public.commerce_products(id), version integer not null check(version > 0), price_type text not null, amount_minor bigint not null check(amount_minor >= 0), currency text not null check(currency ~ '^[A-Z]{3}$'), billing_interval text, stripe_price_id text unique, status text not null check(status in ('draft','active','inactive','archived')), effective_from timestamptz, effective_to timestamptz, created_at timestamptz not null, unique(product_id,version));
create table public.commerce_offers (id text primary key, slug text unique not null, name text not null, product_ids text[] not null, price_ids text[] not null, eligibility_policy_id text references public.commerce_eligibility_policies(id), status text not null, metadata jsonb not null default '{}'::jsonb, available_from timestamptz, available_to timestamptz, created_at timestamptz not null, updated_at timestamptz not null);
create table public.commerce_customers (id text primary key, workspace_id uuid, profile_id uuid, email text not null, stripe_customer_id text unique, status text not null, created_at timestamptz not null);
create table public.commerce_orders (id text primary key, order_number text unique not null, customer_id text not null references public.commerce_customers(id), workspace_id uuid, status text not null check(status in ('draft','pending-payment','cancelled')), currency text not null, subtotal_minor bigint not null, total_minor bigint not null, created_at timestamptz not null, updated_at timestamptz not null);
create table public.commerce_order_lines (id text primary key, order_id text not null references public.commerce_orders(id), product_snapshot jsonb not null, price_snapshot jsonb not null, quantity integer not null check(quantity > 0), line_total_minor bigint not null);
create index commerce_products_catalog_idx on public.commerce_products(status,category_id,slug);
create index commerce_prices_product_status_idx on public.commerce_prices(product_id,status,version desc);
create index commerce_orders_customer_idx on public.commerce_orders(customer_id,created_at desc);
alter table public.commerce_categories enable row level security; alter table public.commerce_products enable row level security; alter table public.commerce_prices enable row level security; alter table public.commerce_offers enable row level security; alter table public.commerce_customers enable row level security; alter table public.commerce_orders enable row level security; alter table public.commerce_order_lines enable row level security; alter table public.commerce_eligibility_policies enable row level security; alter table public.commerce_entitlement_templates enable row level security; alter table public.commerce_fulfillment_templates enable row level security;
create policy "Public reads active Commerce products" on public.commerce_products for select using(status='active' or public.is_admin());
create policy "Public reads active Commerce prices" on public.commerce_prices for select using(status='active' or public.is_admin());
create policy "Public reads active Commerce offers" on public.commerce_offers for select using(status='active' or public.is_admin());
create policy "Admins manage Commerce catalog" on public.commerce_products for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Commerce customers read self" on public.commerce_customers for select to authenticated using(profile_id=auth.uid() or public.is_admin());
create policy "Commerce orders read self" on public.commerce_orders for select to authenticated using(exists(select 1 from public.commerce_customers c where c.id=customer_id and (c.profile_id=auth.uid() or public.is_admin())));
create policy "Commerce lines read through order" on public.commerce_order_lines for select to authenticated using(exists(select 1 from public.commerce_orders o join public.commerce_customers c on c.id=o.customer_id where o.id=order_id and (c.profile_id=auth.uid() or public.is_admin())));
create or replace function public.prevent_commerce_history_change() returns trigger language plpgsql as $$ begin raise exception 'Commerce history is immutable' using errcode='P0001'; end $$;
create trigger commerce_prices_immutable before update or delete on public.commerce_prices for each row when(old.status <> 'draft') execute function public.prevent_commerce_history_change();
create trigger commerce_order_lines_immutable before update or delete on public.commerce_order_lines for each row execute function public.prevent_commerce_history_change();
